  package    net . masterthought . cucumber . generators ;   import    net . masterthought . cucumber . ReportBuilder ;  import      net . masterthought . cucumber . generators . integrations . PageTest ;  import    org . apache . velocity . VelocityContext ;  import   org . junit . Before ;  import   org . junit . Test ;  import static      org . assertj . core . api . Assertions . assertThat ;   public class FeaturesOverviewPageTest  extends PageTest  {    @ Before public void setUp  ( )  {   setUpWithJson  ( SAMPLE_JSON ) ; }    @ Test public void getWebPage_ReturnsFeatureFileName  ( )  {   page =  new FeaturesOverviewPage  ( reportResult , configuration ) ;  String  fileName =  page . getWebPage  ( ) ;    assertThat  ( fileName ) . isEqualTo  (  ReportBuilder . HOME_PAGE ) ; }    @ Test public void prepareReport_AddsCustomProperties  ( )  {   page =  new FeaturesOverviewPage  ( reportResult , configuration ) ;   page . prepareReport  ( ) ;  VelocityContext  context =  page . context ;    assertThat  (  context . getKeys  ( ) ) . hasSize  ( 14 ) ;    assertThat  (  context . get  ( "all_features" ) ) . isEqualTo  ( features ) ;    assertThat  (  context . get  ( "report_summary" ) ) . isEqualTo  (  reportResult . getFeatureReport  ( ) ) ; } }